all_native_theorem_constants.type:
∀ {X Y A : Type u} (q : X → Y) (R : X → A → X → Prop) (S : Set X) (a : A) (y : Y),
  UEOT.V3.Compression.TheoryCompletion.UnifiedClosure.SupportViabilityClosure.relationSuccessor q R S a y =
    {x' | q x' = y ∧ ∃ x ∈ S, R x a x'}

∀ {X Y : Type u} [inst : Fintype X] (q : X → Y),
  UEOT.V3.Compression.TheoryCompletion.UnifiedClosure.SupportViabilityClosure.supportArenaFinset q =
    {S | S ∈ UEOT.V3.Compression.TheoryCompletion.UnifiedClosure.SupportViabilityClosure.supportArena q}

∀ {X Y A : Type u} [inst : Fintype X] (q : X → Y) (R : X → A → X → Prop) (C : X → A → Prop) (k : ℕ),
  UEOT.V3.Compression.TheoryCompletion.UnifiedClosure.SupportViabilityClosure.supportIterateFinset✝ q R C k =
    {S | S ∈ UEOT.V3.Compression.TheoryCompletion.UnifiedClosure.SupportViabilityClosure.supportIterate q R C k}
